import json,datetime,calendar,subprocess,concurrent.futures
def gh(path):
 p=subprocess.run(["gh","api",path],capture_output=True,text=True,timeout=65)
 if p.returncode: raise RuntimeError(path+" "+p.stderr[:400])
 return json.loads(p.stdout)
def pages(endpoint):
 out=[]
 for n in range(1,50):
  arr=gh(endpoint+("&" if "?" in endpoint else "?")+f"per_page=100&page={n}")
  assert isinstance(arr,list)
  out+=arr
  if len(arr)<100:return out
 raise RuntimeError("Pagination exceeded")
now=datetime.datetime.now(datetime.timezone.utc)
m=now.month-6;y=now.year
if m<=0:m+=12;y-=1
first=now.replace(year=y,month=m,day=min(now.day,calendar.monthrange(y,m)[1]))
public=pages("users/BestNameYet/repos?type=all")
installed=gh("installation/repositories?per_page=100&page=1")["repositories"]
repos={r["full_name"]:r for r in public+installed if r.get("owner",{}).get("login","").lower()=="bestnameyet"}
active=sorted((r for r in repos.values() if r.get("pushed_at") and datetime.datetime.fromisoformat(r["pushed_at"].replace("Z","+00:00"))>=first),key=lambda r:r["full_name"].lower())
ext={".yaml",".yml",".js",".mjs",".cjs",".jsx",".html",".htm",".py",".pyw"}
print("CENSUS",json.dumps({"utc_now":now.isoformat(),"window_start":first.isoformat(),"public":len(public),"installed":len(installed),"union":len(repos),"active":len(active)}))
for repo in active:
 name=repo["full_name"]
 try:
  branches=pages("repos/"+name+"/branches")
  detail=[]
  for b in branches:
   sha=b["commit"]["sha"]
   tree=gh("repos/"+name+"/git/trees/"+sha+"?recursive=1")
   hits=[t for t in tree.get("tree",[]) if t["type"]=="blob" and any(t["path"].lower().endswith(e) for e in ext)]
   detail.append({"branch":b["name"],"head":sha,"tree_truncated":tree.get("truncated",False),"tree_items":len(tree.get("tree",[])),"matching_files":len(hits),"match_bytes":sum(int(v.get("size",0)) for v in hits),"sample": [x["path"] for x in hits[:4]]})
  print("REPO",json.dumps({"name":name,"private":repo["private"],"pushed_at":repo["pushed_at"],"branches":detail},ensure_ascii=False))
 except Exception as e:print("ERROR",json.dumps({"name":name,"error":str(e)}))
